PREFIX a: <http://aegis.gastown.local/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?record ?g ?e ?t ?repo ?sha ?actor WHERE {
{ SELECT ("event" AS ?record) ?g ?e ?t ?repo ?sha ?actor WHERE { VALUES ?g { <{monthNow}> <{monthPrev}> } GRAPH ?g { ?e a a:ChangeEvent ; a:occurredAt ?t ; a:changeAction "merged" ; a:changeRepository ?repo ; a:commitSha ?sha . OPTIONAL { ?e a:eventActor ?actor } FILTER(xsd:dateTime(?t)>=xsd:dateTime('{since}') && xsd:dateTime(?t)<xsd:dateTime('{until}')) } } ORDER BY DESC(?t) ?e LIMIT 101 }
UNION { VALUES ?g { <{monthNow}> <{monthPrev}> } GRAPH ?g {} BIND("coverage" AS ?record) }
} LIMIT 104
